sys_script_client.script:
function onSubmit() {
    //Type appropriate comment here, and begin script below
	if(g_form.getValue("ceo_approval")=="false"){
		g_form.setValue("ceo_weightage",0);
	}
	if(g_form.getValue("cfo_approval")=='false'){
		g_form.setValue("cfo_weightage",0);
	}
	if(g_form.getValue("cto_approval")=='false'){
		g_form.setValue("cto_weightage",0);
	}
	if(g_form.getValue("cdo_approval")=='false'){
		g_form.setValue("cdo_weightage",0);
	}
	if(g_form.getValue("coe_lead_approval")=='false'){
		g_form.setValue("parallel_lead_weightage",0);
	}
	if(g_form.getValue("project_manager_approval")=='false'){
		g_form.setValue("manager_weightage",0);
	}
    var lead =parseInt(g_form.getValue("parallel_lead_weightage"));
    var manager = parseInt(g_form.getValue("manager_weightage"));
    var ceo = parseInt(g_form.getValue("ceo_weightage"));
    var cfo = parseInt(g_form.getValue("cfo_weightage"));
    var cdo = parseInt(g_form.getValue("cdo_weightage"));
    var cto = parseInt(g_form.getValue("cto_weightage"));
	var sum=0;
    sum = lead + manager + ceo + cdo + cto + cfo;
	alert(sum);
	if(sum==100){
		"";
	}else{
		g_form.addErrorMessage("The total weightage of all enabled fields should be equal to 100");
	}



}
